import {CLASSES} from './classes.js?v=0.3.1';
export const RARITIES={common:{name:'Звичайний',color:'#b5bcae'},uncommon:{name:'Незвичайний',color:'#9ac684'},rare:{name:'Рідкісний',color:'#88b5e4'},epic:{name:'Епічний',color:'#b89add'},legendary:{name:'Легендарний',color:'#e7bc72'}};
export const SETS={};
const themes={swordsman:'Варти сталі',mage:'Зоряного кола',archer:'Слідопита',acolyte:'Берегині світла',merchant:'Першого горна',thief:'Тихої тіні',gunslinger:'Срібного патрона'};
export function installEquipment(items){for(let t of Object.values(items))t.rarity??='common';for(let [classId,c]of Object.entries(CLASSES))for(let [tier,rarity]of ['uncommon','rare','epic','legendary'].entries()){let level=[10,26,46,68][tier],setId=`${classId}-${tier}`,magic=['mage','acolyte'].includes(classId);SETS[setId]={name:`${themes[classId]} · ${tier+1}`,classId,rarity,level,bonuses:{2:{hp:level*5,def:Math.ceil(level*.3)},3:magic?{matk:level,sp:level*2}:{atk:level,haste:.1}},pieces:[]};for(let slot of ['weapon','armor','accessory']){let id=`set-${setId}-${slot}`;SETS[setId].pieces.push(id);items[id]={name:`${slot==='weapon'?{sword:'Клинок',staff:'Посох',bow:'Лук',gun:'Револьвер',hammer:'Молот',dagger:'Кинджал'}[c.weapon]:slot==='armor'?'Обладунок':'Талісман'} ${themes[classId]}`,kind:slot,slot,weapon:slot==='weapon'?c.weapon:undefined,rarity,set:setId,price:level*50,shop:tier===0,requirements:{level,classes:[classId]},stats:slot==='weapon'?magic?{matk:10+level*1.6}:{atk:10+level*1.5}:slot==='armor'?{def:8+level*.8,hp:20+level*3}:{mdef:level*.5,sp:level*2},desc:`Класовий сет ${CLASSES[classId].name}. Бонус за 2 та 3 споряджені частини.`};}}}
export const BUILDS={swordsman:{name:'Витривалий мечник',weights:{STR:4,VIT:3,DEX:2,AGI:1},reason:'STR — шкода, VIT — запас HP і захист, DEX — влучання. Для соло спершу доведіть VIT до 12.'},mage:{name:'Маг бойового контролю',weights:{INT:5,DEX:3,VIT:2},reason:'INT підсилює магію та SP, DEX скорочує каст. VIT дає запас часу на вихід із телеграфів.'},archer:{name:'Лучник на дистанції',weights:{DEX:5,AGI:3,VIT:2},reason:'DEX — шкода та точність лука; AGI — швидкість атак. Не нехтуйте VIT.'},acolyte:{name:'Цілитель для соло й групи',weights:{INT:5,VIT:3,DEX:2},reason:'INT підсилює лікування, магію й SP; VIT допомагає пережити фокус ворогів.'},merchant:{name:'Бойовий коваль',weights:{STR:4,VIT:4,DEX:2},reason:'STR — удар молота, VIT — витривалість, DEX — надійне влучання.'},thief:{name:'Мобільний отруйник',weights:{AGI:4,STR:3,DEX:2,VIT:1},reason:'AGI скорочує інтервал атак, STR підсилює клинок. Отрута й вампіризм не замінюють запас HP.'},gunslinger:{name:'Влучний револьверник',weights:{DEX:5,AGI:3,VIT:2},reason:'DEX — шкода вогнепальної зброї, AGI — темп пострілів, VIT — страховка під час перекату.'}};
export function recommendedStat(h){let b=BUILDS[h.classId],base=CLASSES[h.classId].stat;return Object.keys(b.weights).filter(k=>h.stats[k]<99).sort((a,c)=>(h.stats[a]-base[a]+1)/b.weights[a]-(h.stats[c]-base[c]+1)/b.weights[c])[0];}
export function xpMultiplier(heroLevel,mobLevel){let gap=heroLevel-mobLevel;if(gap>=7)return 0;if(gap>=5)return .1;if(gap>=3)return .35;return Math.min(1.2,1+Math.max(0,-gap)*.025);}
export function killXP(heroLevel,mobLevel,boss=false,type=null){return Math.floor((22+mobLevel*12)*(boss?2:type==='slime'?.55:1)*xpMultiplier(heroLevel,mobLevel));}
